import React, { useState, useEffect } from 'react';
import Scanner from './components/Scanner';
import MedicineResult from './components/MedicineResult';
import Reminders from './components/Reminders';
import History from './components/History';
import DoctorAI from './components/DoctorAI';
import PremiumModal from './components/PremiumModal';
import Profile from './components/Profile';
import LegalAndHelp from './components/LegalAndHelp';
import { MedicineData, AppView, Reminder, PatientProfile, ScanHistoryItem } from './types';
import { getHealthTip } from './services/geminiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>(AppView.HOME);
  const [scannedData, setScannedData] = useState<MedicineData | null>(null);
  const [patientProfile, setPatientProfile] = useState<PatientProfile | undefined>(undefined);

  const [isPremium, setIsPremium] = useState<boolean>(() => {
    try {
      return localStorage.getItem('mediScan_premium') === 'true';
    } catch {
      return false;
    }
  });

  const [showPremiumModal, setShowPremiumModal] = useState(false);
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [healthTip, setHealthTip] = useState<string>("");
  const [scanHistory, setScanHistory] = useState<ScanHistoryItem[]>([]);
  const [isPreviouslyScanned, setIsPreviouslyScanned] = useState(false);
  const [overdoseWarning, setOverdoseWarning] = useState(false);

  useEffect(() => {
    try {
      if (!localStorage.getItem('mediScan_deviceId')) {
          localStorage.setItem('mediScan_deviceId', crypto.randomUUID());
      }
      const savedReminders = localStorage.getItem('mediScan_reminders');
      if (savedReminders) setReminders(JSON.parse(savedReminders));
      const savedHistory = localStorage.getItem('mediScan_history');
      if (savedHistory) setScanHistory(JSON.parse(savedHistory));
      getHealthTip().then(setHealthTip).catch(() => setHealthTip("Stay hydrated and check expiry dates."));
    } catch (e) {
      console.error("Initialization error", e);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('mediScan_reminders', JSON.stringify(reminders));
  }, [reminders]);

  useEffect(() => {
    localStorage.setItem('mediScan_history', JSON.stringify(scanHistory));
  }, [scanHistory]);

  const handleUpgrade = (txnId?: string) => {
    setIsPremium(true);
    localStorage.setItem('mediScan_premium', 'true');
    if (txnId) localStorage.setItem('mediScan_txnId', txnId);
    setShowPremiumModal(false);
    setCurrentView(AppView.PROFILE);
  };

  const addReminder = (r: Reminder) => setReminders(prev => [...prev, r]);
  const deleteReminder = (id: string) => setReminders(prev => prev.filter(r => r.id !== id));
  const toggleReminder = (id: string) => setReminders(prev => prev.map(r => r.id === id ? { ...r, active: !r.active } : r));

  const handleScanComplete = (data: MedicineData, profile: PatientProfile) => {
    const now = Date.now();
    const fourHours = 4 * 60 * 60 * 1000;
    const recentScan = scanHistory.find(item => {
        const isSameMed = item.medicineName.toLowerCase().trim() === data.name.toLowerCase().trim();
        const isRecent = (now - item.timestamp) < fourHours;
        return isSameMed && isRecent;
    });
    setIsPreviouslyScanned(scanHistory.some(item => item.medicineName.toLowerCase().trim() === data.name.toLowerCase().trim()));
    setOverdoseWarning(!!recentScan);
    setScanHistory(prev => [{ id: crypto.randomUUID(), timestamp: now, medicineName: data.name, data }, ...prev].slice(0, 20));
    setScannedData(data);
    setPatientProfile(profile);
  };

  const renderContent = () => {
    if (scannedData) {
      return <MedicineResult data={scannedData} profile={patientProfile} isPremium={isPremium} isPreviouslyScanned={isPreviouslyScanned} overdoseWarning={overdoseWarning} onOpenPremium={() => setShowPremiumModal(true)} onClose={() => setScannedData(null)} />;
    }

    switch (currentView) {
      case AppView.HOME:
      case AppView.SCANNER:
        return (
          <div className="px-6 pt-10 pb-32 animate-fade-in max-w-lg mx-auto">
            <header className="mb-10 flex justify-between items-center">
               <div className="group cursor-default">
                   <div className="flex items-center space-x-2.5">
                       <h1 className="text-4xl font-extrabold tracking-tighter bg-gradient-to-br from-slate-900 via-teal-800 to-slate-800 bg-clip-text text-transparent">MedScan</h1>
                       <div className="w-2.5 h-2.5 bg-rose-500 rounded-full animate-heartbeat shadow-[0_0_12px_rgba(244,63,94,0.6)]"></div>
                   </div>
                   <p className="text-[10px] font-bold uppercase tracking-[0.3em] text-slate-400 ml-0.5 mt-1.5 opacity-60">AI Health Companion</p>
               </div>
               <div className="flex space-x-3">
                   <button onClick={() => setCurrentView(AppView.INFO)} className="w-11 h-11 bg-white flex items-center justify-center rounded-2xl shadow-xl shadow-slate-200/50 border border-slate-50 text-slate-400 hover:text-teal-600 transition-all active:scale-90">
                       <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                   </button>
               </div>
            </header>

            {healthTip && (
                 <div className="mb-10 p-6 bg-white border border-teal-50/50 rounded-[2.5rem] flex items-start shadow-2xl shadow-teal-900/5 animate-slide-up hover:shadow-teal-900/10 transition-shadow">
                    <div className="w-12 h-12 bg-teal-50 rounded-2xl flex items-center justify-center mr-4 shrink-0 text-2xl shadow-inner">💊</div>
                    <div>
                        <h4 className="text-[10px] font-black text-teal-600/70 uppercase tracking-widest mb-1.5">Smart Tip</h4>
                        <span className="text-sm text-slate-700 font-bold leading-relaxed">{healthTip}</span>
                    </div>
                 </div>
            )}

            <Scanner onScanComplete={handleScanComplete} onError={(msg) => alert(msg)} />

            {!isPremium && (
                <div onClick={() => setShowPremiumModal(true)} className="mt-10 bg-slate-900 text-white p-7 rounded-[3rem] shadow-2xl shadow-slate-900/20 flex justify-between items-center cursor-pointer transform transition-all hover:translate-y-[-2px] active:scale-95 group relative overflow-hidden border border-slate-800">
                    <div className="absolute inset-0 bg-gradient-to-br from-slate-800 to-slate-900 z-0"></div>
                    <div className="absolute -top-12 -right-12 w-48 h-48 bg-white opacity-[0.05] rounded-full blur-3xl group-hover:opacity-10 transition-opacity"></div>
                    <div className="relative z-10">
                        <h3 className="font-extrabold text-xl flex items-center tracking-tight">Expert Insights <span className="ml-2">💎</span></h3>
                        <p className="text-[10px] text-slate-500 mt-1 font-black uppercase tracking-widest opacity-80">Unlock Detailed Safety Reports</p>
                    </div>
                    <div className="relative z-10 bg-white text-slate-900 px-6 py-3 rounded-2xl font-black text-xs shadow-xl tracking-widest uppercase">₹99</div>
                </div>
            )}
          </div>
        );
      case AppView.REMINDERS:
        return <Reminders reminders={reminders} addReminder={addReminder} deleteReminder={deleteReminder} toggleReminder={toggleReminder} />;
      case AppView.HISTORY:
        return <History history={scanHistory} onSelectItem={(data) => { setScannedData(data); setOverdoseWarning(false); setIsPreviouslyScanned(true); }} onClearHistory={() => setScanHistory([])} />;
      case AppView.DOCTOR_AI:
        return <DoctorAI />;
      case AppView.INFO:
          return <LegalAndHelp />;
      case AppView.PROFILE:
          return <Profile isPremium={isPremium} />;
      default:
        return <div className="p-10 text-center">View not found</div>;
    }
  };

  return (
    <div className="max-w-md mx-auto min-h-screen relative shadow-2xl overflow-hidden font-sans text-slate-800">
      <main className="min-h-screen relative z-10 overflow-y-auto hide-scrollbar">
        {renderContent()}
      </main>
      {!scannedData && (
        <nav className="fixed bottom-8 left-4 right-4 max-w-[calc(28rem-2rem)] mx-auto glass rounded-[2.5rem] shadow-2xl shadow-slate-300/40 px-2 py-4 flex justify-around items-center z-40 border border-white/80">
            {[
                { view: AppView.HOME, icon: "M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z M15 13a3 3 0 11-6 0 3 3 0 016 0z", label: "Scan" },
                { view: AppView.REMINDERS, icon: "M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z", label: "Alarms" },
                { view: AppView.DOCTOR_AI, icon: "M16 7a4 4 0 11-8 0 4 4 0 018 0z", label: "Doctor" },
                { view: AppView.HISTORY, icon: "M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z", label: "History" },
                { view: AppView.PROFILE, icon: "M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z", label: "Pro" }
            ].map((item) => {
                const isActive = currentView === item.view || (item.view === AppView.HOME && currentView === AppView.SCANNER);
                return (
                    <button key={item.label} onClick={() => (item.view === AppView.PROFILE && !isPremium) ? setShowPremiumModal(true) : setCurrentView(item.view)} className={`flex flex-col items-center justify-center w-12 h-12 rounded-2xl transition-all duration-500 ${isActive ? 'bg-slate-900 text-white shadow-2xl shadow-slate-900/30' : 'text-slate-400 hover:text-slate-600'}`}>
                        <svg className={`w-4 h-4 mb-1 ${isActive ? 'stroke-2' : 'stroke-[1.5]'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" d={
                            item.view === AppView.DOCTOR_AI ? "M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" : 
                            item.view === AppView.HISTORY ? "M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" : 
                            item.icon
                          } />
                        </svg>
                        <span className={`text-[7px] font-black tracking-widest uppercase ${isActive ? 'opacity-100' : 'opacity-60'}`}>{item.label}</span>
                    </button>
                );
            })}
        </nav>
      )}
      <PremiumModal isOpen={showPremiumModal} onClose={() => setShowPremiumModal(false)} onUpgrade={handleUpgrade} />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { MedicineData, PatientProfile } from '../types';
import { checkConditionSafety } from '../services/geminiService';

interface MedicineResultProps {
  data: MedicineData;
  profile?: PatientProfile;
  isPremium: boolean;
  isPreviouslyScanned: boolean;
  overdoseWarning?: boolean;
  onOpenPremium: () => void;
  onClose: () => void;
}

const MedicineResult: React.FC<MedicineResultProps> = ({ 
    data, 
    profile, 
    isPremium, 
    isPreviouslyScanned, 
    overdoseWarning,
    onOpenPremium, 
    onClose 
}) => {
  const [speaking, setSpeaking] = useState(false);
  const [showCriticalModal, setShowCriticalModal] = useState(false);
  const [useEli5, setUseEli5] = useState(false);
  const [expandedDesc, setExpandedDesc] = useState(false);
  const [activeChip, setActiveChip] = useState<number | null>(null); 
  const [activeTimelineTooltip, setActiveTimelineTooltip] = useState<string | null>(null);

  // Decision Support
  const [selectedCondition, setSelectedCondition] = useState('');
  const [conditionSafety, setConditionSafety] = useState('');
  const [checkingCondition, setCheckingCondition] = useState(false);

  // Safety Defaults
  const questions = data?.commonQuestions || [];
  const timeline = data?.effectTimeline || { onset: 'N/A', peak: 'N/A', duration: 'N/A' };
  const lifestyle = data?.lifestyleWarnings || { alcohol: false, driving: false, sleep: false };
  const avoidList = data?.whoShouldAvoid || [];
  const alternatives = data?.alternatives || [];

  useEffect(() => {
    if (data?.riskScore === 'High' || data?.criticalWarning || overdoseWarning) {
        setShowCriticalModal(true);
    }
    return () => { window.speechSynthesis.cancel(); }
  }, [data, overdoseWarning]);

  const speakText = (text: string) => {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = profile?.language === 'hindi' ? 'hi-IN' : 'en-US';
    utterance.onend = () => setSpeaking(false);
    window.speechSynthesis.speak(utterance);
    setSpeaking(true);
  };

  const toggleSpeech = () => {
    if (speaking) {
        window.speechSynthesis.cancel();
        setSpeaking(false);
    } else {
        const textToRead = `${data?.name}. ${useEli5 ? data?.childFriendlyExplanation : data?.simpleExplanation}. ${data?.keyWarning || ''}`;
        speakText(textToRead);
    }
  };

  const readWarningAloud = () => {
    const textToRead = overdoseWarning 
        ? "Attention! Potential Overdose detected. A recent scan of this medicine was found. Double-dosing can be very dangerous."
        : `Warning. ${data?.criticalWarning || 'High Risk Alert'}. ${data?.riskReason || ''}`;
    speakText(textToRead);
  };

  const handleShare = async () => {
      const shareData = {
          title: `MedScan: ${data?.name}`,
          text: `Medicine: ${data?.name}. Risk Level: ${data?.riskScore}.`,
          url: window.location.href
      };
      try {
          if (navigator.share) await navigator.share(shareData);
      } catch (err) {}
  };

  const handleCheckCondition = async () => {
      if (!selectedCondition || !data?.name) return;
      setCheckingCondition(true);
      const result = await checkConditionSafety(data.name, selectedCondition);
      setConditionSafety(result);
      setCheckingCondition(false);
  };

  const handleDownloadReport = () => {
      if (!isPremium) {
          onOpenPremium();
          return;
      }
      window.print();
  };

  const getHeaderColor = () => {
      if (overdoseWarning || data?.riskScore === 'High') return 'bg-rose-600';
      if (data?.riskScore === 'Medium') return 'bg-amber-500';
      return 'bg-teal-600';
  };

  const timelineDefs: Record<string, string> = {
    onset: "When the medicine starts working in your body.",
    peak: "When the medicine reaches its maximum strength.",
    duration: "How long the relief typically lasts."
  };

  if (!data) return null;

  return (
    <div className="bg-slate-50 min-h-screen pb-32 animate-fade-in relative z-50">

        {/* CRITICAL WARNING MODAL */}
        {showCriticalModal && (
            <div className="fixed inset-0 z-[60] bg-slate-900/95 flex items-center justify-center p-6 backdrop-blur-md animate-fade-in">
                <div className="bg-white rounded-[2.5rem] p-8 shadow-2xl w-full max-w-sm text-center border-t-4 border-rose-500 relative">
                     <button 
                        onClick={readWarningAloud}
                        className="absolute top-6 right-6 w-10 h-10 bg-rose-50 rounded-full flex items-center justify-center text-rose-500 hover:bg-rose-100 transition-colors active:scale-90"
                        title="Read Warning Aloud"
                     >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg>
                     </button>

                     <div className="w-20 h-20 bg-rose-100 rounded-full flex items-center justify-center mx-auto mb-6 animate-pulse">
                         <span className="text-4xl">⚠️</span>
                     </div>
                     <h2 className="text-2xl font-extrabold text-rose-600 mb-2 leading-tight">{overdoseWarning ? 'Potential Overdose' : 'High Risk Alert'}</h2>
                     <p className="text-slate-600 font-medium mb-6 leading-relaxed px-2">
                         {overdoseWarning 
                            ? "Recent scan detected. Double-dosing can be dangerous. Please confirm intake time."
                            : (data?.criticalWarning || "This medicine carries risks for your current profile.")}
                     </p>

                     {data?.riskReason && (
                         <div className="bg-rose-50 p-5 rounded-2xl mb-8 text-sm text-rose-800 border border-rose-100 font-bold text-left flex items-start">
                             <span className="mr-3 mt-0.5">🚨</span>
                             <span>{data.riskReason}</span>
                         </div>
                     )}

                     <div className="space-y-3">
                        <button onClick={() => { setShowCriticalModal(false); window.speechSynthesis.cancel(); }} className="w-full bg-rose-600 text-white py-4 rounded-2xl font-black shadow-lg shadow-rose-200 transition-all active:scale-95 uppercase tracking-widest text-xs">
                            I Understand
                        </button>
                        <button onClick={readWarningAloud} className="w-full bg-slate-50 text-slate-400 py-3 rounded-xl font-bold text-[10px] uppercase tracking-widest hover:bg-slate-100 transition-colors">
                            {speaking ? "Speaking..." : "Listen to Warning"}
                        </button>
                     </div>
                </div>
            </div>
        )}

        {/* Hero Header */}
        <header className={`${getHeaderColor()} text-white rounded-b-[3rem] shadow-2xl shadow-slate-300 relative overflow-hidden pb-12`}>
            <div className="absolute top-0 right-0 -mr-20 -mt-20 w-80 h-80 bg-white opacity-10 rounded-full blur-3xl"></div>

            <div className="p-6 pt-8 relative z-10">
                <div className="flex justify-between items-start mb-6">
                    <div className="flex flex-wrap gap-2">
                         <div className="bg-black/20 backdrop-blur-md px-3 py-1.5 rounded-lg border border-white/10">
                            <span className="text-[10px] font-bold tracking-widest uppercase">Risk: {data?.riskScore || 'Unknown'}</span>
                        </div>
                        {isPreviouslyScanned && (
                             <div className="bg-blue-500/30 backdrop-blur-md px-3 py-1.5 rounded-lg border border-blue-400/30">
                                <span className="text-[10px] font-bold">History Found</span>
                            </div>
                        )}
                    </div>
                    <button onClick={onClose} className="bg-white/10 p-2.5 rounded-full hover:bg-white/20 active:scale-95 print:hidden border border-white/10">
                        <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>

                <h2 className="text-3xl font-extrabold mb-2 tracking-tight">{data?.name || 'Unknown Medicine'}</h2>
                <div 
                    className={`text-white/90 text-sm font-medium leading-relaxed transition-all ${expandedDesc ? '' : 'line-clamp-2'}`} 
                    onClick={() => setExpandedDesc(!expandedDesc)}
                >
                    {data?.description || 'No description available.'}
                </div>
                {!expandedDesc && (data?.description?.length || 0) > 80 && (
                    <button onClick={() => setExpandedDesc(true)} className="text-[10px] uppercase font-bold text-white/70 mt-2 tracking-widest">Read More</button>
                )}

                {data?.keyWarning && (
                    <div className="mt-6 bg-black/20 backdrop-blur-md p-4 rounded-2xl border-l-4 border-yellow-400">
                        <p className="text-sm font-bold text-white">⚠️ {data.keyWarning}</p>
                    </div>
                )}
            </div>

            <button 
                onClick={toggleSpeech}
                className="absolute -bottom-7 right-8 w-16 h-16 bg-yellow-400 rounded-full shadow-lg flex items-center justify-center text-slate-900 active:scale-95 transition-transform z-20 print:hidden border-4 border-white"
            >
                {speaking ? (
                    <div className="flex space-x-1 items-center h-5">
                        <div className="w-1.5 h-6 bg-slate-900 animate-pulse"></div>
                        <div className="w-1.5 h-6 bg-slate-900 animate-pulse delay-75"></div>
                    </div>
                ) : (
                    <svg className="w-7 h-7 ml-1" fill="currentColor" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
                )}
            </button>
        </header>

        <div className="px-5 pt-12 space-y-6">

            <section className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest">AI Analysis</h3>
                    <button 
                        onClick={() => setUseEli5(!useEli5)}
                        className={`text-[10px] font-bold px-3 py-1.5 rounded-full transition-all border ${useEli5 ? 'bg-indigo-50 text-indigo-700 border-indigo-200' : 'bg-slate-50 text-slate-500 border-slate-200'}`}
                    >
                        {useEli5 ? 'Simple Mode' : 'Explain Simply'}
                    </button>
                </div>
                <p className="text-slate-800 text-lg font-medium leading-relaxed">
                    "{useEli5 ? data?.childFriendlyExplanation : data?.simpleExplanation}"
                </p>

                <div className="mt-8">
                    <div className="flex justify-between text-[10px] font-bold text-slate-400 mb-2 uppercase tracking-wider">
                        <span>Caution</span>
                        <span>Safety: {data?.safetyRating || 0}%</span>
                        <span>Safe</span>
                    </div>
                    <div className="h-3 w-full bg-slate-100 rounded-full overflow-hidden p-0.5">
                        <div 
                            className={`h-full rounded-full transition-all duration-1000 ${ (data?.safetyRating || 0) > 70 ? 'bg-teal-500' : (data?.safetyRating || 0) > 40 ? 'bg-amber-500' : 'bg-rose-500'}`} 
                            style={{width: `${data?.safetyRating || 0}%`}}
                        ></div>
                    </div>
                </div>
            </section>

            {questions.length > 0 && (
                <div>
                    <h4 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-3 ml-1">Follow-up</h4>
                    <div className="no-scrollbar overflow-x-auto flex space-x-3 pb-2 -mx-5 px-5">
                        {questions.map((q, idx) => (
                            <button
                                key={idx}
                                onClick={() => setActiveChip(activeChip === idx ? null : idx)}
                                className={`flex-shrink-0 px-4 py-2.5 rounded-2xl text-xs font-bold border transition-all ${activeChip === idx ? 'bg-teal-600 text-white border-teal-600 shadow-md' : 'bg-white text-slate-600 border-slate-200'}`}
                            >
                                {q.question}
                            </button>
                        ))}
                    </div>
                    {activeChip !== null && (
                        <div className="bg-teal-50 p-5 rounded-2xl border border-teal-100 mt-2 animate-slide-up">
                            <p className="text-sm font-bold text-teal-900">{questions[activeChip].answer}</p>
                        </div>
                    )}
                </div>
            )}

             <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 relative">
                <h3 className="text-xs font-bold text-slate-400 uppercase mb-8 tracking-widest flex items-center">
                    Effect Timeline
                    <span className="ml-2 w-4 h-4 rounded-full border border-slate-200 text-slate-400 text-[8px] flex items-center justify-center font-black">?</span>
                </h3>

                <div className="relative px-4 pb-4">
                    {/* The Connecting Line */}
                    <div className="absolute top-[18px] left-6 right-6 h-1.5 bg-slate-100 -z-10 rounded-full overflow-hidden">
                        <div className="h-full w-full bg-gradient-to-r from-blue-400 via-purple-400 to-emerald-400 opacity-30"></div>
                    </div>

                    <div className="flex justify-between items-start">
                        {[
                            { id: 'onset', label: "Starts", val: timeline.onset, color: "bg-blue-500", shadow: "shadow-blue-200" },
                            { id: 'peak', label: "Peak", val: timeline.peak, color: "bg-purple-500", shadow: "shadow-purple-200" },
                            { id: 'duration', label: "Lasts", val: timeline.duration, color: "bg-emerald-500", shadow: "shadow-emerald-200" }
                        ].map((item, i) => (
                            <button 
                                key={i} 
                                className="flex flex-col items-center focus:outline-none transition-transform active:scale-95"
                                onClick={() => setActiveTimelineTooltip(activeTimelineTooltip === item.id ? null : item.id)}
                            >
                                <div className={`w-9 h-9 ${item.color} rounded-2xl border-4 border-white shadow-lg ${item.shadow} flex items-center justify-center mb-3 group`}>
                                     {item.id === 'onset' && <span className="text-white text-[10px]">⏱️</span>}
                                     {item.id === 'peak' && <span className="text-white text-[10px]">📈</span>}
                                     {item.id === 'duration' && <span className="text-white text-[10px]">⌛</span>}
                                </div>
                                <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mb-1">{item.label}</p>
                                <p className="text-xs font-black text-slate-900">{item.val}</p>
                            </button>
                        ))}
                    </div>

                    {/* Tooltip Content */}
                    {activeTimelineTooltip && (
                        <div className="mt-6 bg-slate-900 text-white p-4 rounded-2xl text-[10px] font-bold animate-slide-up relative">
                             <div className="absolute -top-1.5 left-1/2 -translate-x-1/2 w-3 h-3 bg-slate-900 rotate-45"></div>
                             <span className="opacity-60 uppercase tracking-widest block mb-1">{activeTimelineTooltip}:</span>
                             {timelineDefs[activeTimelineTooltip]}
                        </div>
                    )}
                </div>
             </div>

             <div className="grid grid-cols-2 gap-4">
                 <section className="bg-orange-50/50 p-5 rounded-[2rem] border border-orange-100">
                     <span className="text-[10px] font-bold text-orange-400 uppercase mb-2 tracking-widest">Intake</span>
                     <div className="flex items-center mt-1">
                         <span className="text-2xl mr-2">🥣</span>
                         <span className="font-bold text-slate-900 text-sm leading-tight">{data?.foodGuidance || 'Anytime'}</span>
                     </div>
                 </section>

                 <div className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm">
                     <span className="text-[10px] font-bold text-slate-400 uppercase mb-3 tracking-widest">Restrictions</span>
                     <div className="flex justify-between w-full">
                         <div className={`text-xl ${!lifestyle.alcohol && 'opacity-20 grayscale'}`} title="No Alcohol">🍷</div>
                         <div className={`text-xl ${!lifestyle.driving && 'opacity-20 grayscale'}`} title="No Driving">🚗</div>
                         <div className={`text-xl ${!lifestyle.sleep && 'opacity-20 grayscale'}`} title="Drowsiness">💤</div>
                     </div>
                 </div>
             </div>

            {avoidList.length > 0 && (
                <div className="bg-rose-50 p-6 rounded-[2rem] border border-rose-100">
                    <h3 className="text-xs font-bold text-rose-800 uppercase mb-4 tracking-widest">Avoid If</h3>
                    <div className="flex flex-wrap gap-2">
                        {avoidList.map((item, i) => (
                            <span key={i} className="px-3 py-1.5 bg-white text-rose-700 rounded-lg text-xs font-bold border border-rose-100">
                                {item}
                            </span>
                        ))}
                    </div>
                </div>
            )}

            <section className="bg-blue-50/50 p-6 rounded-[2rem] border border-blue-100">
                <h3 className="text-xs font-bold text-blue-900 uppercase mb-4 tracking-widest">Safety Check</h3>
                <div className="flex flex-wrap gap-2 mb-4">
                    {['Fever', 'High BP', 'Diabetes', 'Asthma'].map(c => (
                        <button 
                            key={c} 
                            onClick={() => { setSelectedCondition(c); setConditionSafety(''); }}
                            className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all border ${selectedCondition === c ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-slate-600 border-slate-200'}`}
                        >
                            {c}
                        </button>
                    ))}
                </div>
                {selectedCondition && (
                    <div className="bg-white p-4 rounded-2xl border border-blue-100 shadow-sm">
                         <button 
                            onClick={handleCheckCondition}
                            className="w-full bg-blue-100 text-blue-700 py-2 rounded-lg text-xs font-bold hover:bg-blue-200 mb-2"
                            disabled={checkingCondition}
                         >
                             {checkingCondition ? 'Checking...' : `Check for ${selectedCondition}`}
                         </button>
                         {conditionSafety && (
                             <p className="text-sm font-bold text-slate-800 bg-blue-50 p-3 rounded-xl">{conditionSafety}</p>
                         )}
                    </div>
                )}
            </section>

            {alternatives.length > 0 && (
                <section className="bg-indigo-50/50 p-6 rounded-[2rem] border border-indigo-100">
                    <h3 className="text-xs font-bold text-indigo-900 uppercase mb-4 tracking-widest">Suggested Alternatives</h3>
                    <div className="flex flex-wrap gap-2">
                        {alternatives.map((alt, i) => (
                            <div key={i} className="flex items-center bg-white px-4 py-2 rounded-xl border border-indigo-100 shadow-sm transition-transform active:scale-95">
                                <span className="text-xs font-bold text-slate-800">{alt}</span>
                                <div className="ml-2 w-5 h-5 bg-indigo-50 rounded-full flex items-center justify-center text-[8px]">💊</div>
                            </div>
                        ))}
                    </div>
                    <p className="text-[9px] font-bold text-indigo-400 mt-4 uppercase tracking-tighter opacity-70">Always discuss alternatives with your physician.</p>
                </section>
            )}

            <div className="space-y-3 pt-2 print:hidden">
                <button 
                    onClick={handleDownloadReport}
                    className={`w-full py-4 rounded-2xl font-bold shadow-lg flex items-center justify-center transition-all ${isPremium ? 'bg-slate-900 text-white' : 'bg-gradient-to-r from-yellow-400 to-orange-500 text-slate-900'}`}
                >
                    <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                    {isPremium ? 'Download Health Report' : 'Unlock PDF Report (Premium)'}
                </button>

                <button 
                    onClick={handleShare}
                    className="w-full bg-white text-teal-700 py-4 rounded-2xl font-bold border border-slate-100 shadow-sm flex items-center justify-center"
                >
                    Share Information
                </button>
            </div>

            <p className="text-center text-[10px] text-slate-400 font-bold uppercase tracking-widest pb-10">
                AI can make mistakes. Verify with a doctor.
            </p>
        </div>
    </div>
  );
};

export default MedicineResult;

export type AgeGroup = 'child' | 'adult' | 'senior';
export type Gender = 'male' | 'female';
export type Language = 'english' | 'hindi' | 'hinglish';

export interface PatientProfile {
  ageGroup: AgeGroup;
  gender: Gender;
  isPregnant: boolean;
  isBreastfeeding: boolean;
  language: Language;
}

export type RiskScore = 'Low' | 'Medium' | 'High';

export interface InteractionRisk {
  severity: 'Safe' | 'Warning' | 'Dangerous';
  summary: string;
  advice: string;
}

export interface MedicineData {
  name: string; // If multiple, this could be a summary name like "Medication Pack"
  medicationsFound: string[]; // List of all detected meds
  description: string;
  simpleExplanation: string;
  childFriendlyExplanation: string;
  uses: string[];
  dosage: string;
  sideEffects: string[];
  warnings: string;
  keyWarning: string;
  riskScore: RiskScore;
  riskReason: string;
  whoShouldAvoid: string[];
  foodGuidance: string; 
  alternatives: string[];

  interactionAnalysis?: InteractionRisk; // NEW: Detailed analysis of the combination

  effectTimeline: {
      onset: string;
      peak: string;
      duration: string;
  };
  lifestyleWarnings: {
      alcohol: boolean;
      driving: boolean;
      sleep: boolean;
  };
  safetyRating: number;
  commonQuestions: {
      question: string;
      answer: string;
