import React, { useState, useRef, useEffect } from 'react';
import { ChatMessage } from '../types';
import { getDoctorAIResponse } from '../services/geminiService';

const DoctorAI: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>(() => {
    try {
      const saved = localStorage.getItem('mediScan_chat_history');
      if (saved) return JSON.parse(saved);
    } catch (e) {
      console.error("Failed to load chat history", e);
    }
    return [
      {
        id: 'welcome',
        role: 'assistant',
        content: 'Hello! I am your MedScan Doctor AI. How can I help you today? Please remember, I am an AI, not a human doctor.',
        timestamp: Date.now()
      }
    ];
  });

  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('mediScan_chat_history', JSON.stringify(messages));
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async (text: string) => {
    if (!text.trim() || isLoading) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: text,
      timestamp: Date.now()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      const responseText = await getDoctorAIResponse([...messages, userMsg]);

      const assistantMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: responseText,
        timestamp: Date.now()
      };

      setMessages(prev => [...prev, assistantMsg]);
    } catch (error) {
      console.error("Chat error", error);
    } finally {
      setIsLoading(false);
    }
  };

  const clearChat = () => {
    if (confirm("Clear all chat history?")) {
      const welcome = {
        id: 'welcome',
        role: 'assistant',
        content: 'Hello! I am your MedScan Doctor AI. How can I help you today? Please remember, I am an AI, not a human doctor.',
        timestamp: Date.now()
      };
      setMessages([welcome]);
      localStorage.removeItem('mediScan_chat_history');
    }
  };

  const quickPrompts = [
    "I have a mild fever",
    "Should I take Advil for headache?",
    "Healthy breakfast tips",
    "How to treat a burn?"
  ];

  return (
    <div className="flex flex-col h-screen max-w-lg mx-auto bg-slate-50 relative">
      {/* Header */}
      <header className="p-6 pt-10 bg-white border-b border-slate-100 shrink-0 relative z-30">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
             <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-2xl shadow-lg shadow-indigo-200">
               👨‍⚕️
             </div>
             <div>
               <h2 className="text-xl font-black text-slate-900 tracking-tight">Doctor AI</h2>
               <div className="flex items-center">
                 <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse mr-2"></div>
                 <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Active Consultant</span>
               </div>
             </div>
          </div>
          {messages.length > 1 && (
            <button 
              onClick={clearChat}
              className="p-2 text-slate-400 hover:text-rose-500 transition-colors"
              title="Clear Chat"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
            </button>
          )}
        </div>
      </header>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-6 space-y-6 pb-48 no-scrollbar">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-slide-up`}>
            <div className={`max-w-[85%] p-4 rounded-[1.8rem] shadow-sm text-sm leading-relaxed ${
              msg.role === 'user' 
                ? 'bg-indigo-600 text-white rounded-br-none' 
                : 'bg-white text-slate-800 rounded-bl-none border border-slate-100'
            }`}>
              {msg.content.split('\n').map((line, i) => (
                <p key={i} className={i > 0 ? 'mt-2' : ''}>{line}</p>
              ))}
              <p className={`text-[8px] mt-2 font-bold uppercase tracking-widest ${msg.role === 'user' ? 'text-indigo-200' : 'text-slate-300'}`}>
                {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </p>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start animate-fade-in">
            <div className="bg-white p-4 rounded-[1.8rem] rounded-bl-none border border-slate-100 shadow-sm flex space-x-1.5">
               <div className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce"></div>
               <div className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce delay-75"></div>
               <div className="w-1.5 h-1.5 bg-slate-300 rounded-full animate-bounce delay-150"></div>
            </div>
          </div>
        )}
        <div ref={scrollRef} />
      </div>

      {/* Input Area */}
      <div className="fixed bottom-32 left-0 right-0 p-6 z-20 max-w-lg mx-auto">
        {messages.length < 3 && !isLoading && (
           <div className="flex overflow-x-auto no-scrollbar space-x-2 mb-4">
             {quickPrompts.map(p => (
               <button key={p} onClick={() => handleSend(p)} className="shrink-0 bg-white border border-slate-200 text-slate-600 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-50 transition-all active:scale-95 shadow-sm">
                 {p}
               </button>
             ))}
           </div>
        )}

        <div className="glass rounded-[2rem] p-2 shadow-2xl border border-white flex items-center">
          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSend(input)}
            placeholder="Ask anything..."
            className="flex-1 bg-transparent border-none focus:ring-0 text-slate-800 text-sm font-bold px-4 placeholder-slate-400"
          />
          <button 
            onClick={() => handleSend(input)}
            disabled={!input.trim() || isLoading}
            className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${input.trim() ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 text-slate-300'}`}
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 10l7-7m0 0l7 7m-7-7v18" /></svg>
          </button>
        </div>
        <p className="text-center text-[8px] font-black text-slate-400 uppercase tracking-widest mt-4">Consult a physical doctor for emergencies</p>
      </div>
    </div>
  );
};

