import React, { useEffect, useRef, useState } from 'react';
import { Reminder } from '../types';

interface AlarmRingingModalProps {
  reminder: Reminder;
  onTake: () => void;
  onSnooze: (minutes: number) => void;
  onSkip: () => void;
}

const AlarmRingingModal: React.FC<AlarmRingingModalProps> = ({ reminder, onTake, onSnooze, onSkip }) => {
  const [volumeLevel, setVolumeLevel] = useState(0.3);
  const audioContextRef = useRef<AudioContext | null>(null);
  const intervalRef = useRef<number | null>(null);
  const customAudioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    if (navigator.vibrate) {
        const pattern = reminder.soundType === 'loud' || reminder.soundType === 'emergency' ? [500, 200, 500, 200] : [200, 1000];
        navigator.vibrate(pattern);
        const vibeInterval = setInterval(() => navigator.vibrate(pattern), 2000);
        return () => { clearInterval(vibeInterval); navigator.vibrate(0); };
    }
  }, [reminder.soundType]);

  useEffect(() => {
    let stopAudio = () => {};

    if (reminder.soundType === 'voice') {
       const speak = () => {
           window.speechSynthesis.cancel();
           const tone = reminder.voiceTone || 'normal';
           const foodStr = reminder.foodContext.replace('_', ' ');

           let text = '';
           if (tone === 'hindi') {
               text = `Namaste! Yeh aapki dawai ${reminder.medicineName} lene ka samay hai. Aapko ${reminder.dose} dawai ${foodStr} leni hai. Kripya ise abhi lein aur apna khayal rakhein. Main fir se dohra rahi hoon: Dawai ka naam hai ${reminder.medicineName}.`;
           } else if (tone === 'strict') {
               text = `Attention! Critical health reminder. You must take ${reminder.dose} of ${reminder.medicineName} immediately. This should be taken ${foodStr}. Please confirm ingestion now. Repeating: ${reminder.medicineName}. Now.`;
           } else if (tone === 'friendly') {
               text = `Hi there! It's time for your medication. Don't forget your ${reminder.dose} of ${reminder.medicineName}. Remember to take it ${foodStr}. Have a wonderful day!`;
           } else {
               text = `Time for your medicine. Please take ${reminder.dose} of ${reminder.medicineName} ${foodStr}. This is a scheduled reminder for your wellness.`;
           }

           const utterance = new SpeechSynthesisUtterance(text);
           if (tone === 'hindi') utterance.lang = 'hi-IN';
           utterance.rate = 0.9; // Slightly slower for clarity
           window.speechSynthesis.speak(utterance);
       };

       speak();
       const voiceInterval = setInterval(speak, 12000); // Repeat every 12 seconds
       stopAudio = () => { clearInterval(voiceInterval); window.speechSynthesis.cancel(); };
    } else if (reminder.soundType === 'custom' && reminder.customSoundData) {
        const audio = new Audio(reminder.customSoundData);
        audio.loop = true;
        audio.volume = volumeLevel;
        customAudioRef.current = audio;
        audio.play().catch(e => console.error("Audio play failed", e));
        stopAudio = () => { audio.pause(); audio.currentTime = 0; };
    } else {
       try {
           const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
           audioContextRef.current = ctx;
           const playPattern = (vol: number) => {
               const playTone = (freq: number, start: number, duration: number, type: OscillatorType = 'sine') => {
                    const osc = ctx.createOscillator();
                    const g = ctx.createGain();
                    osc.type = type;
                    osc.frequency.setValueAtTime(freq, ctx.currentTime + start);
                    g.gain.setValueAtTime(0, ctx.currentTime + start);
                    g.gain.linearRampToValueAtTime(vol, ctx.currentTime + start + 0.05);
                    g.gain.linearRampToValueAtTime(0, ctx.currentTime + start + duration);
                    osc.connect(g); g.connect(ctx.destination);
                    osc.start(ctx.currentTime + start); osc.stop(ctx.currentTime + start + duration);
               };

               if (reminder.soundType === 'soft') playTone(300, 0, 0.5);
               else if (reminder.soundType === 'loud') { playTone(800, 0, 0.3, 'square'); playTone(800, 0.4, 0.3, 'square'); }
               else if (reminder.soundType === 'zen') { playTone(200, 0, 1, 'sine'); playTone(300, 0.5, 1, 'sine'); }
               else if (reminder.soundType === 'emergency') { for(let i=0; i<4; i++) playTone(1200 - (i*100), i*0.15, 0.1, 'sawtooth'); }
               else if (reminder.soundType === 'musical') { playTone(440, 0, 0.2, 'triangle'); playTone(554.37, 0.2, 0.2, 'triangle'); playTone(659.25, 0.4, 0.4, 'triangle'); }
               else if (reminder.soundType === 'ringtone') { for(let i=0; i<3; i++) { playTone(600, i*0.2, 0.1); playTone(800, i*0.2 + 0.1, 0.1); } }
               else playTone(440, 0, 0.3, 'square');
           };
           playPattern(volumeLevel);
           const toneInterval = window.setInterval(() => playPattern(volumeLevel), reminder.soundType === 'emergency' || reminder.soundType === 'ringtone' ? 1000 : 2500);
           intervalRef.current = toneInterval;
           stopAudio = () => { if (intervalRef.current) clearInterval(intervalRef.current); if (ctx.state !== 'closed') ctx.close(); };
       } catch (e) {}
    }
    return stopAudio;
  }, [reminder, volumeLevel]);

  useEffect(() => {
      const volInterval = setInterval(() => {
          setVolumeLevel(p => {
              const next = Math.min(p + 0.1, 1.0);
              if (customAudioRef.current) customAudioRef.current.volume = next;
              return next;
          });
      }, 5000);
      return () => clearInterval(volInterval);
  }, []);

  return (
    <div className="fixed inset-0 z-[1000] bg-slate-900 flex items-center justify-center p-6 animate-fade-in">
      <div className="bg-white w-full max-w-sm rounded-[3.5rem] shadow-2xl overflow-hidden text-center relative border border-slate-100">
        <div className="bg-teal-600 p-12 flex justify-center relative">
            <div className="absolute inset-0 bg-gradient-to-br from-teal-500 to-emerald-700"></div>
            <div className="relative">
                <div className="absolute inset-0 bg-white rounded-full animate-ping opacity-20"></div>
                <div className="bg-white rounded-[2.5rem] p-8 relative z-10 text-teal-600 shadow-2xl animate-bounce">
                    <svg className="w-14 h-14" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9" /></svg>
                </div>
            </div>
        </div>
        <div className="p-10 space-y-6 bg-white">
            <div>
                <h2 className="text-3xl font-black text-slate-900 tracking-tighter mb-1 leading-none">{reminder.medicineName}</h2>
                <p className="text-teal-600 font-black text-xl tracking-tight uppercase">{reminder.dose}</p>
            </div>
            <div className="inline-block bg-slate-100 text-slate-600 px-6 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-slate-200">
                Rule: {reminder.foodContext.replace('_', ' ')}
            </div>
            <div className="space-y-4 pt-4">
                <button onClick={onTake} className="w-full bg-slate-900 text-white py-6 rounded-[2.5rem] font-black text-lg shadow-2xl hover:scale-[1.02] active:scale-95 transition-all">💊 I Have Taken It</button>
                <div className="grid grid-cols-2 gap-4">
                    <button onClick={() => onSnooze(10)} className="bg-slate-50 text-slate-500 py-5 rounded-3xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-100 border border-slate-100">Snooze 10m</button>
                    <button onClick={() => onSnooze(30)} className="bg-slate-50 text-slate-500 py-5 rounded-3xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-100 border border-slate-100">Snooze 30m</button>
                </div>
                <button onClick={() => confirm("Skipping a dose is not recommended. Are you sure?") && onSkip()} className="text-rose-400 text-[10px] font-black uppercase tracking-widest underline opacity-60 mt-4 block mx-auto">Skip Dose</button>
            </div>
        </div>
      </div>
    </div>
  );
};

export default AlarmRingingModal;

import React, { useState, useEffect } from 'react';
import Scanner from './components/Scanner';
import MedicineResult from './components/MedicineResult';
import Reminders from './components/Reminders';
import History from './components/History';
import DoctorAI from './components/DoctorAI';
import PremiumModal from './components/PremiumModal';
import Profile from './components/Profile';
import LegalAndHelp from './components/LegalAndHelp';
import AlarmRingingModal from './components/AlarmRingingModal';
import { MedicineData, AppView, Reminder, PatientProfile, ScanHistoryItem } from './types';
import { getHealthTip } from './services/geminiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>(AppView.HOME);
  const [scannedData, setScannedData] = useState<MedicineData | null>(null);
  const [patientProfile, setPatientProfile] = useState<PatientProfile | undefined>(undefined);

  const [isPremium, setIsPremium] = useState<boolean>(() => {
    try {
      return localStorage.getItem('mediScan_premium') === 'true';
    } catch {
      return false;
    }
  });

  const [showPremiumModal, setShowPremiumModal] = useState(false);
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [healthTip, setHealthTip] = useState<string>("");
  const [scanHistory, setScanHistory] = useState<ScanHistoryItem[]>([]);
  const [isPreviouslyScanned, setIsPreviouslyScanned] = useState(false);
  const [overdoseWarning, setOverdoseWarning] = useState(false);
  const [activeAlarm, setActiveAlarm] = useState<Reminder | null>(null);

  useEffect(() => {
    try {
      if (!localStorage.getItem('mediScan_deviceId')) {
          localStorage.setItem('mediScan_deviceId', crypto.randomUUID());
      }
      const savedReminders = localStorage.getItem('mediScan_reminders');
      if (savedReminders) setReminders(JSON.parse(savedReminders));
      const savedHistory = localStorage.getItem('mediScan_history');
      if (savedHistory) setScanHistory(JSON.parse(savedHistory));
      getHealthTip().then(setHealthTip).catch(() => setHealthTip("Stay hydrated and check expiry dates."));
    } catch (e) {
      console.error("Initialization error", e);
    }

    // Alarm Check Logic
    const interval = setInterval(() => {
        const now = new Date();
        const currentTime = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;

        const triggered = reminders.find(r => r.active && r.time === currentTime && (!r.snoozedUntil || Date.now() >= r.snoozedUntil));
        if (triggered && !activeAlarm) {
            setActiveAlarm(triggered);
        }
    }, 10000);

    return () => clearInterval(interval);
  }, [reminders, activeAlarm]);

  useEffect(() => {
    localStorage.setItem('mediScan_reminders', JSON.stringify(reminders));
  }, [reminders]);

  useEffect(() => {
    localStorage.setItem('mediScan_history', JSON.stringify(scanHistory));
  }, [scanHistory]);

  const handleUpgrade = (txnId?: string) => {
    setIsPremium(true);
    localStorage.setItem('mediScan_premium', 'true');
    if (txnId) localStorage.setItem('mediScan_txnId', txnId);
    setShowPremiumModal(false);
    setCurrentView(AppView.PROFILE);
  };

  const addReminder = (r: Reminder) => setReminders(prev => [...prev, r]);
  const deleteReminder = (id: string) => setReminders(prev => prev.filter(r => r.id !== id));
  const toggleReminder = (id: string) => setReminders(prev => prev.map(r => r.id === id ? { ...r, active: !r.active } : r));

  const handleScanComplete = (data: MedicineData, profile: PatientProfile) => {
    const now = Date.now();
    const fourHours = 4 * 60 * 60 * 1000;
    const recentScan = scanHistory.find(item => {
        const isSameMed = item.medicineName.toLowerCase().trim() === data.name.toLowerCase().trim();
        const isRecent = (now - item.timestamp) < fourHours;
        return isSameMed && isRecent;
    });
    setIsPreviouslyScanned(scanHistory.some(item => item.medicineName.toLowerCase().trim() === data.name.toLowerCase().trim()));
    setOverdoseWarning(!!recentScan);
    setScanHistory(prev => [{ id: crypto.randomUUID(), timestamp: now, medicineName: data.name, data }, ...prev].slice(0, 20));
    setScannedData(data);
    setPatientProfile(profile);
  };

  const renderContent = () => {
    if (scannedData) {
      return <MedicineResult data={scannedData} profile={patientProfile} isPremium={isPremium} isPreviouslyScanned={isPreviouslyScanned} overdoseWarning={overdoseWarning} onOpenPremium={() => setShowPremiumModal(true)} onClose={() => setScannedData(null)} />;
    }

    switch (currentView) {
      case AppView.HOME:
      case AppView.SCANNER:
        return (
          <div className="px-6 pt-10 pb-52 animate-fade-in max-w-lg mx-auto bg-slate-50 min-h-screen">
            <header className="mb-10 flex justify-between items-center bg-slate-50 relative z-20">
               <div className="group cursor-default">
                   <div className="flex items-center space-x-2.5">
                       <h1 className="text-4xl font-extrabold tracking-tighter bg-gradient-to-br from-slate-900 via-teal-800 to-slate-800 bg-clip-text text-transparent">MedScan</h1>
                       <div className="w-2.5 h-2.5 bg-rose-500 rounded-full animate-heartbeat shadow-[0_0_12px_rgba(244,63,94,0.6)]"></div>
                   </div>
                   <p className="text-[10px] font-bold uppercase tracking-[0.3em] text-slate-400 ml-0.5 mt-1.5 opacity-60">AI Health Companion</p>
               </div>
