type Step = 'INFO' | 'PAYMENT' | 'VERIFY' | 'RESTORE';

const PremiumModal: React.FC<PremiumModalProps> = ({ isOpen, onClose, onUpgrade }) => {
  const [step, setStep] = useState<Step>('INFO');
  const [txnId, setTxnId] = useState('');
