// Simulate sending OTP
export const sendOTP = async (email: string): Promise<boolean> => {
    // Simulate network delay
    await new Promise(resolve => setTimeout(resolve, 1500));

    // In a real app, integrate with an email provider here.
    // For this demo, we assume success.
    console.log(`[MedScan Auth] OTP requested for ${email}`);

    // Simple validation
    if (!email.includes('@')) throw new Error("Invalid email address");

    return true;
};

// Simulate verifying OTP
export const verifyOTP = async (email: string, otp: string): Promise<User> => {
    // Simulate network delay
    await new Promise(resolve => setTimeout(resolve, 1500));

    // For demo purposes, accept '123456' or any 6-digit code that ends in 0 for failure testing
    if (otp.length === 6) {
        if (otp === '000000') throw new Error("Invalid OTP code"); // Simulating error

        return {
            id: btoa(email), // Simple deterministic ID for demo
            email: email,
            isGuest: false,
            joinedAt: Date.now()
        };
    }

    throw new Error("Invalid code format. Must be 6 digits.");
};

export const getStoredUser = (): User | null => {
    try {
        const stored = localStorage.getItem('mediScan_currentUser');
        return stored ? JSON.parse(stored) : null;
    } catch (e) {
        return null;
    }
};

export const saveUserSession = (user: User) => {
    localStorage.setItem('mediScan_currentUser', JSON.stringify(user));
};

export const clearUserSession = () => {
    localStorage.removeItem('mediScan_currentUser');
};

import React, { useState } from 'react';
import { sendOTP, verifyOTP } from '../services/authService';
import { User } from '../types';

interface AuthModalProps {
  isOpen: boolean;
  onClose: () => void;
  onLoginSuccess: (user: User) => void;
}

const AuthModal: React.FC<AuthModalProps> = ({ isOpen, onClose, onLoginSuccess }) => {
  const [step, setStep] = useState<'EMAIL' | 'OTP'>('EMAIL');
  const [email, setEmail] = useState('');
  const [otp, setOtp] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  if (!isOpen) return null;

  const handleSendOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email) return;
    setIsLoading(true);
    setError('');
    try {
      await sendOTP(email);
      setStep('OTP');
      // For demo convenience, alert the user the code
      alert(`MedScan Demo: Your OTP code is 123456`);
    } catch (err: any) {
      setError(err.message || "Failed to send OTP");
    } finally {
      setIsLoading(false);
    }
  };

  const handleVerify = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!otp) return;
    setIsLoading(true);
    setError('');
    try {
      const user = await verifyOTP(email, otp);
      onLoginSuccess(user);
      onClose();
      // Reset state after close
      setTimeout(() => {
        setStep('EMAIL');
        setEmail('');
        setOtp('');
      }, 500);
    } catch (err: any) {
      setError(err.message || "Invalid Code");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fade-in">
      <div className="bg-white w-full max-w-sm rounded-[2.5rem] shadow-2xl overflow-hidden relative border border-slate-100 animate-slide-up">
        <button onClick={onClose} className="absolute top-5 right-5 z-10 p-2 bg-slate-50 text-slate-400 rounded-full hover:bg-slate-100 transition-colors">
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
        </button>

        <div className="p-8 pt-12">
            <div className="w-16 h-16 bg-teal-50 rounded-2xl flex items-center justify-center mb-6 text-3xl shadow-inner mx-auto">
                🔐
            </div>

            <h2 className="text-2xl font-black text-center text-slate-900 mb-2">
                {step === 'EMAIL' ? 'Welcome Back' : 'Verify Identity'}
            </h2>
            <p className="text-center text-slate-400 text-xs font-bold uppercase tracking-widest mb-8">
                {step === 'EMAIL' ? 'Secure Login / Sign Up' : `Code sent to ${email}`}
            </p>

            {error && (
                <div className="bg-rose-50 text-rose-500 px-4 py-3 rounded-xl text-xs font-bold mb-6 flex items-center justify-center">
                    <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                    {error}
                </div>
            )}

            {step === 'EMAIL' ? (
                <form onSubmit={handleSendOtp} className="space-y-4">
                    <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Email Address</label>
                        <input 
                            type="email" 
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            placeholder="name@example.com"
                            required
                            className="w-full bg-slate-50 border border-slate-100 text-slate-800 font-bold p-4 rounded-2xl focus:ring-4 focus:ring-teal-500/10 focus:border-teal-500 outline-none transition-all placeholder:font-medium"
                        />
                    </div>
                    <button 
                        type="submit" 
                        disabled={isLoading}
                        className="w-full bg-slate-900 text-white font-black py-4 rounded-2xl shadow-lg shadow-slate-900/20 active:scale-95 transition-all disabled:opacity-70 disabled:cursor-not-allowed flex justify-center items-center"
                    >
                        {isLoading ? (
                            <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                        ) : "Continue Securely"}
                    </button>
                    <p className="text-center text-[10px] text-slate-400 font-medium mt-4">We'll send you a One-Time Password.</p>
                </form>
            ) : (
                <form onSubmit={handleVerify} className="space-y-4">
                     <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Enter Code</label>
                        <input 
                            type="text" 
                            value={otp}
                            onChange={(e) => setOtp(e.target.value)}
                            placeholder="123456"
                            maxLength={6}
                            required
                            className="w-full bg-slate-50 border border-slate-100 text-slate-800 font-mono text-center text-2xl tracking-widest p-4 rounded-2xl focus:ring-4 focus:ring-teal-500/10 focus:border-teal-500 outline-none transition-all placeholder:text-slate-300"
                        />
                    </div>
                    <button 
                        type="submit" 
                        disabled={isLoading}
                        className="w-full bg-teal-600 text-white font-black py-4 rounded-2xl shadow-lg shadow-teal-600/20 active:scale-95 transition-all disabled:opacity-70 disabled:cursor-not-allowed flex justify-center items-center"
                    >
                         {isLoading ? (
                            <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                        ) : "Verify & Login"}
                    </button>
                    <button 
                        type="button"
                        onClick={() => setStep('EMAIL')}
                        className="w-full text-slate-400 text-xs font-bold py-2 hover:text-slate-600"
                    >
                        Change Email
                    </button>
                </form>
            )}
        </div>
      </div>
    </div>
  );
};

export default AuthModal;

