          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
        </button>

        <div className="p-8 pt-12">
            <div className="w-16 h-16 bg-teal-50 rounded-2xl flex items-center justify-center mb-6 text-3xl shadow-inner mx-auto">
                🔐
            </div>

            <h2 className="text-2xl font-black text-center text-slate-900 mb-2">
                {step === 'EMAIL' ? 'Welcome Back' : 'Verify Identity'}
            </h2>
            <p className="text-center text-slate-400 text-xs font-bold uppercase tracking-widest mb-8">
                {step === 'EMAIL' ? 'Secure Login / Sign Up' : `Code sent to ${email}`}
            </p>

            {error && (
                <div className="bg-rose-50 text-rose-500 px-4 py-3 rounded-xl text-xs font-bold mb-6 flex items-center justify-center">
                    <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                    {error}
                </div>
            )}

            {step === 'EMAIL' ? (
                <form onSubmit={handleSendOtp} className="space-y-4">
                    <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Email Address</label>
