                        className="w-full bg-slate-900 text-white font-black py-4 rounded-2xl shadow-lg shadow-slate-900/20 active:scale-95 transition-all disabled:opacity-70 disabled:cursor-not-allowed flex justify-center items-center"
                    >
                        {isLoading ? (
                            <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                        ) : "Continue Securely"}
                    </button>
                    <p className="text-center text-[10px] text-slate-400 font-medium mt-4">We'll send you a One-Time Password.</p>
                </form>
            ) : (
                <form onSubmit={handleVerify} className="space-y-4">
                     {/* Demo OTP Banner */}
                     <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-2xl flex items-center justify-between animate-fade-in mb-2">
                        <div className="flex items-center space-x-3">
                             <div className="w-8 h-8 bg-indigo-100 rounded-full flex items-center justify-center text-indigo-600">
                                📩
                             </div>
                             <div>
                                 <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Demo OTP Code</p>
                                 <p className="text-lg font-black text-indigo-900">123456</p>
                             </div>
                        </div>
                        <button 
                            type="button"
                            onClick={() => { setOtp('123456'); }}
                            className="text-xs font-bold text-indigo-600 bg-white px-3 py-1.5 rounded-lg border border-indigo-100 active:scale-95 shadow-sm"
                        >
                            Auto Fill
                        </button>
                    </div>

                     <div className="space-y-2">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Enter Code</label>
                        <input 
