import { 
    sendSignInLinkToEmail, 
    isSignInWithEmailLink, 
    signInWithEmailLink, 
    signOut as firebaseSignOut,
    onAuthStateChanged,
    User as FirebaseUser
} from "firebase/auth";
import { auth } from "../firebaseConfig";
import { User } from "../types";

// Send the magic link
export const sendLoginLink = async (email: string): Promise<void> => {
    const actionCodeSettings = {
        // URL you want to redirect back to. The domain (www.example.com) for this
        // URL must be in the authorized domains list in the Firebase Console.
        url: window.location.href,
        handleCodeInApp: true,
    };

    try {
        await sendSignInLinkToEmail(auth, email, actionCodeSettings);
        // Save the email locally so you don't need to ask the user for it again
        // if they open the link on the same device.
        window.localStorage.setItem('emailForSignIn', email);
    } catch (error: any) {
        console.error("Error sending email link", error);
        throw new Error(error.message || "Failed to send login link.");
    }
};

// Check if the current URL is a sign-in link and complete login
export const checkAndCompleteLogin = async (): Promise<User | null> => {
    if (isSignInWithEmailLink(auth, window.location.href)) {
        let email = window.localStorage.getItem('emailForSignIn');

        if (!email) {
            // User opened the link on a different device. To prevent session fixation
            // attacks, ask the user to provide the associated email again.
            email = window.prompt('Please provide your email for confirmation');
        }

        if (email) {
            try {
                const result = await signInWithEmailLink(auth, email, window.location.href);
                // Clear email from storage
                window.localStorage.removeItem('emailForSignIn');

                // Clear the URL hash to look clean
                window.history.replaceState({}, document.title, window.location.pathname);

                return mapFirebaseUser(result.user);
            } catch (error: any) {
                console.error("Error signing in with email link", error);
                // Some error occurred, you can inspect the code: error.code
                // Common errors: invalid email, link expired, etc.
                throw new Error("Login link expired or invalid. Please try again.");
            }
        }
    }
    return null;
};

// Map Firebase user to App User
export const mapFirebaseUser = (fu: FirebaseUser): User => {
    return {
        uid: fu.uid,
        email: fu.email,
        isGuest: false,
        joinedAt: parseInt(fu.metadata.creationTime ? new Date(fu.metadata.creationTime).getTime().toString() : Date.now().toString())
    };
};

// Sign out
export const logoutUser = async () => {
    await firebaseSignOut(auth);
};

// Sync Premium Status (Local Only - Firestore Disabled)
export const syncUserPremiumStatus = async (uid: string, localIsPremium: boolean): Promise<boolean> => {
    // Firestore sync disabled for stability. Relying on local storage.
    return localIsPremium;
};

